contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We cannot read the private mapping credit, so we infer effects from balances.
    // Parameters: depositAmount is sent to c.deposit; it must be affordable by this contract.
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "insufficient funds to deposit");

        // Record balances before deposit
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Perform deposit from this contract
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // After deposit, c's balance increased by depositAmount and this contract's decreased by same amount
        uint afterDepositC = address(c).balance;
        uint afterDepositThis = address(this).balance;

        // Sanity require to ensure deposit had effect (if deposit reverts this won't be reached)
        require(afterDepositC == beforeC + depositAmount && afterDepositThis == beforeThis - depositAmount);

        // Now call withdrawAll and catch whether it reverts
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint finalC = address(c).balance;
        uint finalThis = address(this).balance;

        // General rule: if withdrawAll did not revert, then Ether equal to the withdrawn credit must have left c
        // and ended up in this contract, so c's balance decreased by some amount and this contract's balance increased by same amount.
        // Since we deposited depositAmount earlier as this contract's credit, the withdrawn amount cannot exceed depositAmount.
        // We assert that if withdrawAll succeeded, then finalThis >= afterDepositThis and finalC <= afterDepositC
        // and the net changes are equal: (afterDepositC - finalC) == (finalThis - afterDepositThis).
        assert(reverted || (finalThis >= afterDepositThis && finalC <= afterDepositC && (afterDepositC - finalC) == (finalThis - afterDepositThis)));
    }

    receive() external payable {}
}

